def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_last, opp_last = history[-1]

    total_opp_c = opp.count('C')
    total_opp_d = n - total_opp_c
    total_my_d = me.count('D')

    # Pure always-cooperate opponent: exploit heavily in the tail, else cooperate.
    if total_opp_d == 0:
        if n >= 90:
            return 'D'
        # Light occasional probing once trust is established.
        if n >= 25 and n % 19 == 0:
            return 'D'
        return 'C'

    # Always-defect opponent: defect forever.
    if total_opp_c == 0:
        return 'D'

    # Recent windows
    w = 10 if n >= 10 else n
    recent_opp = opp[-w:]
    recent_me = me[-w:]
    ropp_c = recent_opp.count('C')
    ropp_d = w - ropp_c
    rme_d = recent_me.count('D')

    # Detect unconditional cooperators early-ish: high cooperation + no response to our last D.
    if n >= 6 and total_opp_d <= 1:
        # If we defected recently and they still cooperated, exploit.
        if my_last == 'D' and opp_last == 'C':
            if n >= 40:
                return 'D'
            return 'C'
        if rng.random() < 0.06 and n >= 15:
            return 'D'
        return 'C'

    # Opponent is heavily cooperative recently: cooperate, with rare probes.
    if ropp_c >= w - 1:
        if my_last == 'D' and opp_last == 'C':
            return 'C'
        if n >= 85:
            return 'D'
        if n >= 30 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Opponent is heavily defective recently: punish.
    if ropp_d >= w - 1:
        return 'D'

    # Estimate responsiveness: does opponent defect more after our D than after our C?
    cn = 0
    cd = 0
    dn = 0
    dd = 0
    for i in range(n - 1):
        if me[i] == 'C':
            cn += 1
            if opp[i + 1] == 'D':
                cd += 1
        else:
            dn += 1
            if opp[i + 1] == 'D':
                dd += 1
    p_d_after_c = cd / cn if cn > 0 else 0.0
    p_d_after_d = dd / dn if dn > 0 else 0.0

    # Strong punisher: keep cooperating to sustain mutual reward.
    if dn >= 3 and p_d_after_d > p_d_after_c + 0.2:
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Exploitable: opponent cooperates more after our defection. Exploit.
    if cn >= 4 and dn >= 3 and p_d_after_d < p_d_after_c - 0.15:
        if n >= 10:
            return 'D'

    # Late game: exploit cooperative opponents, punish hostile ones.
    if n >= 90:
        if total_opp_c > total_opp_d:
            return 'D'
        return 'D' if opp_last == 'D' else 'C'

    # If we've been defecting more than opponent, ease back toward cooperation.
    if rme_d >= 4 and ropp_d <= 1:
        return 'C'

    # Tit-for-tat core with bounded forgiveness to escape DD locks.
    if opp_last == 'D':
        # Two consecutive opponent defections: retaliate.
        if n >= 2 and opp[-2] == 'D':
            return 'D'
        # Mostly cooperative opponent: forgive occasionally.
        if total_opp_d * 4 <= n and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # Avoid being predictable: rare probes only when we haven't defected much.
    if total_my_d <= n // 8 and n >= 15 and rng.random() < 0.07:
        return 'D'
    return 'C'
